
let view='bookmarks',editing=null,selected=null,revision=1;let bookmarks=[{id:'b1',title:'Example reference',url:'https://example.com/reference',folder:'Reading'},{id:'b2',title:'Example home',url:'https://example.com/',folder:'Favorites'}],history=[{id:'h1',title:'Today’s reading',url:'https://example.com/read',visitedAt:new Date().toISOString()},{id:'h2',title:'Earlier guide',url:'https://example.com/guide',visitedAt:new Date(Date.now()-86400000*3).toISOString()}];
function draw(){const q=document.getElementById('filter').value.toLowerCase(),folder=document.getElementById('folder').value,box=document.getElementById('entries');box.replaceChildren();(view==='bookmarks'?bookmarks:history).filter(x=>(x.title+' '+x.url).toLowerCase().includes(q)&&(view!=='bookmarks'||folder==='All folders'||x.folder===folder)).forEach(x=>{const row=document.createElement('section');row.className='card compact row spread';row.style.flexDirection='row';const text=document.createElement('div'),h=document.createElement('h2'),p=document.createElement('p');h.style.fontSize='1.3rem';h.textContent=x.title;p.textContent=view==='bookmarks'?x.folder:new Date(x.visitedAt).toLocaleString();text.append(h,p);const actions=document.createElement('div');actions.className='row';const open=document.createElement('button');open.textContent='Open';open.onclick=()=>r2.request('navigation.open',{url:x.url},()=>true).then(()=>r2.toast('Open requested in preview.')).catch(e=>r2.toast(e.message));actions.append(open);if(view==='bookmarks'){const more=document.createElement('button');more.textContent='More';more.onclick=()=>{selected=x.id;obUI.openDialog('entry-options')};actions.append(more)}row.append(text,actions);box.append(row)});if(!box.children.length)box.innerHTML='<p class="empty">Nothing here yet.</p>'}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));['folder-label','add','folder-add'].forEach(id=>document.getElementById(id).hidden=view==='history');['range-label','clear'].forEach(id=>document.getElementById(id).hidden=view!=='history');draw()});document.getElementById('filter').oninput=draw;document.getElementById('folder').onchange=draw;
function edit(id){editing=id;const x=bookmarks.find(x=>x.id===id)||{title:'',url:'https://',folder:'Favorites'};document.getElementById('title').value=x.title;document.getElementById('url').value=x.url;document.getElementById('edit-folder').value=x.folder;document.getElementById('entry-options').close();obUI.openDialog('edit-dialog')};document.getElementById('add').onclick=()=>edit(null);document.getElementById('edit-entry').onclick=()=>edit(selected);
document.getElementById('edit').onsubmit=async e=>{e.preventDefault();const url=r2.url(document.getElementById('url').value);if(!url){document.getElementById('edit-error').textContent='Use an HTTP or HTTPS address.';return}const entry={id:editing||'b'+Date.now(),title:document.getElementById('title').value.trim(),url,folder:document.getElementById('edit-folder').value};try{await r2.request('bookmarks.put',{revision,entry},()=>true);bookmarks=bookmarks.filter(x=>x.id!==entry.id).concat(entry);revision++;document.getElementById('edit-dialog').close();draw();obUI.focus(document.getElementById('add'))}catch(err){document.getElementById('edit-error').textContent=err.message}};
document.getElementById('delete-entry').onclick=async()=>{try{await r2.request('bookmarks.remove',{id:selected,revision},()=>true);bookmarks=bookmarks.filter(x=>x.id!==selected);revision++;document.getElementById('entry-options').close();draw();obUI.focus(document.getElementById('add'))}catch(e){r2.toast(e.message)}};document.getElementById('clear').onclick=()=>obUI.openDialog('confirm');document.getElementById('confirm-clear').onclick=async()=>{const range=document.getElementById('range').value,after=range==='all'?0:Date.now()-(range==='hour'?3600000:86400000);try{await r2.request('history.clear',{after:new Date(after).toISOString(),before:new Date().toISOString(),confirmed:true},()=>true);history=history.filter(x=>new Date(x.visitedAt).getTime()<after);document.getElementById('confirm').close();draw();obUI.focus(document.getElementById('clear'))}catch(e){r2.toast(e.message)}};
document.getElementById('folder-add').onclick=()=>obUI.openDialog('folder-dialog');document.getElementById('folder-form').onsubmit=async e=>{e.preventDefault();const name=document.getElementById('folder-name').value.trim();if(!name)return;try{await r2.request('bookmarks.folder.create',{name},()=>true);for(const id of ['folder','edit-folder']){const select=document.getElementById(id);if(![...select.options].some(o=>o.value===name))select.add(new Option(name,name))}document.getElementById('folder-dialog').close();obUI.focus(document.getElementById('folder-add'))}catch(err){r2.toast(err.message)}};draw();